//! Storage abstraction. File bytes live in a backend under an opaque key (a
//! UUID generated by the app); the database records which backend and key
//! each file uses, so different backends can coexist later.

mod local;
mod smb;

use std::collections::HashMap;
use std::io;
use std::path::Path;
use std::pin::Pin;
use std::sync::Arc;

use async_trait::async_trait;
use bytes::Bytes;
use futures_util::Stream;
use tokio::io::AsyncRead;

pub use local::LocalFs;
pub use smb::SmbShare;

use crate::config::{Config, StorageKind};
use crate::fsid::FileIdentity;

/// A stream of chunks to store (e.g. a multipart upload field).
pub type ByteStream<'a> = Pin<Box<dyn Stream<Item = io::Result<Bytes>> + Send + 'a>>;
/// A reader over (part of) a stored object.
pub type ByteReader = Pin<Box<dyn AsyncRead + Send>>;

#[derive(Debug, thiserror::Error)]
pub enum StorageError {
    #[error("invalid storage key")]
    InvalidKey,
    #[error("object not found")]
    NotFound,
    #[error("not implemented: {0}")]
    NotImplemented(&'static str),
    #[error("unknown storage backend '{0}'")]
    UnknownBackend(String),
    #[error("size mismatch after copy (expected {expected} bytes, got {actual})")]
    SizeMismatch { expected: u64, actual: u64 },
    #[error("source is not a regular file")]
    NotARegularFile,
    #[error("the source file was replaced or modified during the import")]
    Changed,
    #[error(transparent)]
    Io(#[from] io::Error),
}

#[async_trait]
pub trait StorageBackend: Send + Sync {
    /// Identifier stored in `files.storage_backend`.
    fn name(&self) -> &'static str;

    /// Stores a stream under `key`, chunk by chunk. Returns the byte count.
    /// The object only becomes visible once fully written.
    async fn put(&self, key: &str, data: ByteStream<'_>) -> Result<u64, StorageError>;

    /// Moves a local file (from INCOMING_PATH) into storage under `key`.
    /// `expect` pins the file that was validated and hashed: if `src` no
    /// longer names that unchanged inode, nothing is stored
    /// ([`StorageError::Changed`]). The source is gone afterwards. Returns
    /// the stored byte count.
    async fn import_from_path(
        &self,
        key: &str,
        src: &Path,
        expect: FileIdentity,
    ) -> Result<u64, StorageError>;

    /// Opens `len` bytes of an object starting at `offset` (for Range requests).
    async fn open(&self, key: &str, offset: u64, len: u64) -> Result<ByteReader, StorageError>;

    /// Deletes an object. Deleting a missing object is not an error.
    async fn delete(&self, key: &str) -> Result<(), StorageError>;

    /// Size of an object, or None if it does not exist.
    async fn size(&self, key: &str) -> Result<Option<u64>, StorageError>;

    async fn exists(&self, key: &str) -> Result<bool, StorageError> {
        Ok(self.size(key).await?.is_some())
    }
}

/// Generates a new opaque storage key.
pub fn new_key() -> String {
    uuid::Uuid::new_v4().to_string()
}

/// All configured backends, plus the one new files go to.
pub struct StorageRegistry {
    active: Arc<dyn StorageBackend>,
    all: HashMap<&'static str, Arc<dyn StorageBackend>>,
}

impl StorageRegistry {
    pub fn from_config(config: &Config) -> io::Result<Self> {
        let local: Arc<dyn StorageBackend> = Arc::new(LocalFs::new(&config.storage_path)?);
        let smb: Arc<dyn StorageBackend> = Arc::new(SmbShare);
        let active = match config.storage_backend {
            StorageKind::Local => local.clone(),
            StorageKind::Smb => {
                tracing::warn!(
                    "STORAGE_BACKEND=smb is a stub: imports, uploads and downloads will fail. \
                     See docs/STORAGE.md (mount the share on the host and use 'local')."
                );
                smb.clone()
            }
        };
        let all = HashMap::from([(local.name(), local), (smb.name(), smb)]);
        Ok(Self { active, all })
    }

    pub fn active(&self) -> Arc<dyn StorageBackend> {
        self.active.clone()
    }

    pub fn get(&self, name: &str) -> Result<Arc<dyn StorageBackend>, StorageError> {
        self.all
            .get(name)
            .cloned()
            .ok_or_else(|| StorageError::UnknownBackend(name.to_string()))
    }
}
